func RunWithReaper(ctx context.Context, cfg Config, temporalWorker TemporalWorker, reaper OrphanRunReaper, logger *slog.Logger) error {
	logger.Info("starting worker",
		"task_queue", cfg.TaskQueue,
		"identity", cfg.Identity,
		"temporal_address", cfg.TemporalAddress,
		"temporal_namespace", cfg.TemporalNamespace,
	)

	if err := temporalWorker.Start(); err != nil {
		return fmt.Errorf("start temporal worker: %w", err)
	}

	reaperDoneCh := make(chan struct{})
	if reaper != nil {
		go func() {
			defer close(reaperDoneCh)
			reaper.Start(ctx)
		}()
	} else {
		close(reaperDoneCh)
	}

	<-ctx.Done()

	logger.Info("stopping worker", "shutdown_timeout", cfg.ShutdownTimeout.String())

	stoppedCh := make(chan struct{}, 1)
	go func() {
		temporalWorker.Stop()
		stoppedCh <- struct{}{}
	}()

	timer := time.NewTimer(cfg.ShutdownTimeout)
	defer timer.Stop()

	workerStopped := false
	reaperStopped := false
	for !workerStopped || !reaperStopped {
		select {
		case <-stoppedCh:
			workerStopped = true
			stoppedCh = nil
		case <-reaperDoneCh:
			reaperStopped = true
			reaperDoneCh = nil
		case <-timer.C:
			return fmt.Errorf("worker shutdown timed out after %s", cfg.ShutdownTimeout)
		}
	}
	return nil
}

